(() => {
  const encodedDiagrams = {"structurizr-01-system-context.svg":"","structurizr-02-container-microservices.svg":"","structurizr-03a-component-asm-api.svg":"","structurizr-03b-component-api-asm-plus.svg":"","structurizr-03c-component-api-auth.svg":"","structurizr-03d-component-api-sap.svg":"","structurizr-03e-component-api-sf.svg":"","structurizr-03f-component-front-asm-plus.svg":"","structurizr-03g-component-front-auth.svg":"","structurizr-03h-component-front-viewer.svg":"","structurizr-04-api-integration.svg":"","structurizr-05-data-architecture.svg":"","structurizr-06-deployment-architecture.svg":"","structurizr-07-network-architecture.svg":"","structurizr-08-security-architecture.svg":"","structurizr-09a-runtime-sso.svg":"","structurizr-09b-runtime-upload.svg":"","structurizr-09c-runtime-view.svg":"","structurizr-09d-runtime-sap.svg":"","structurizr-09e-runtime-successfactors.svg":"","structurizr-10-observability-architecture.svg":""};

  function forceSvgDownload(event) {
    const link = event.currentTarget;
    const fileName = link.getAttribute("download");
    const encodedSvg = encodedDiagrams[fileName];
    if (!encodedSvg) return;

    event.preventDefault();
    event.stopPropagation();

    const binary = atob(encodedSvg);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);

    const objectUrl = URL.createObjectURL(new Blob([bytes], { type: "image/svg+xml;charset=utf-8" }));
    const transfer = document.createElement("a");
    transfer.href = objectUrl;
    transfer.download = fileName;
    transfer.hidden = true;
    document.body.append(transfer);
    transfer.click();
    transfer.remove();
    window.setTimeout(() => URL.revokeObjectURL(objectUrl), 1000);
  }

  document.addEventListener("DOMContentLoaded", () => {
    document.querySelectorAll(".diagram-download, #download-svg-link").forEach((link) => {
      link.addEventListener("click", forceSvgDownload);
    });
  });
})();
